function depositCollateral(bytes32 subAccountId, uint256 collateralAmount) external payable {
        LibSubAccount.DecodedSubAccountId memory account = subAccountId.decodeSubAccountId();
        address msgSender = _msgSender();
        address accountOwner = subAccountId.getSubAccountOwner();
        if (_storage.aggregators[msgSender]) {
            // we trust aggregator
        } else {
            // otherwise only account owner can place order
            require(accountOwner == msgSender, "SND"); // SeNDer is not authorized
        }
        require(collateralAmount != 0, "C=0"); // Collateral Is Zero
        address collateralAddress = _storage.pool.getAssetAddress(account.collateralId);
        LibOrderBook._transferIn(_storage, accountOwner, collateralAddress, address(_storage.pool), collateralAmount);
        _storage.pool.depositCollateral(subAccountId, collateralAmount);
    }

function depositCollateral(
        bytes32 subAccountId,
        uint256 rawAmount // NOTE: OrderBook SHOULD transfer rawAmount collateral to LiquidityPool
    ) external onlyOrderBook {
        LibSubAccount.DecodedSubAccountId memory decoded = subAccountId.decodeSubAccountId();
        require(decoded.account != address(0), "T=0"); // Trader address is zero
        require(_hasAsset(decoded.collateralId), "LST"); // the asset is not LiSTed
        require(_hasAsset(decoded.assetId), "LST"); // the asset is not LiSTed
        require(rawAmount != 0, "A=0"); // Amount Is Zero

        SubAccount storage subAccount = _storage.accounts[subAccountId];
        Asset storage asset = _storage.assets[decoded.assetId];
        Asset storage collateral = _storage.assets[decoded.collateralId];
        require(asset.isEnabled(), "ENA"); // the token is temporarily not ENAbled
        require(collateral.isEnabled(), "ENA"); // the token is temporarily not ENAbled
        uint96 wadAmount = collateral.toWad(rawAmount);
        subAccount.collateral += wadAmount;

        emit DepositCollateral(subAccountId, decoded.account, decoded.collateralId, rawAmount, wadAmount);
        _updateSequence();
    }

function depositCollateral(
        OrderBookStorage storage orderBook,
        bytes32 positionId,
        address collateralToken,
        uint256 collateralAmount
    ) external {
        require(collateralAmount != 0, "Zero collateral");
        LibOrderBook._transferIn(orderBook, collateralToken, collateralAmount);
        LibOrderBook._transferOut(orderBook, collateralToken, address(orderBook.mux3Facet), collateralAmount, false);
        IFacetPositionAccount(orderBook.mux3Facet).deposit(positionId, collateralToken, collateralAmount);
    }

function depositCollateral(
        bytes32 positionId,
        address collateralToken,
        uint256 collateralAmount // token decimals
    ) external payable nonReentrant updateSequence {
        (address positionAccount, ) = LibCodec.decodePositionId(positionId);
        if (_isDelegator(msg.sender)) {
            // pass
        } else {
            require(positionAccount == msg.sender, "Not authorized");
        }
        LibOrderBook2.depositCollateral(_storage, positionId, collateralToken, collateralAmount);
    }

function placePositionOrder3(
        bytes32 subAccountId,
        uint96 collateralAmount, // erc20.decimals
        uint96 size, // 1e18
        uint96 price, // 1e18
        uint8 profitTokenId,
        uint8 flags,
        uint32 deadline, // 1e0
        bytes32 referralCode,
        PositionOrderExtra memory extra
    ) public payable nonReentrant {
        address msgSender = _msgSender();
        address accountOwner = subAccountId.getSubAccountOwner();
        if (_storage.aggregators[msgSender]) {
            // we trust aggregator
        } else {
            // otherwise only account owner can place order
            require(accountOwner == msgSender, "SND"); // SeNDer is not authorized
        }
        if (referralCode != bytes32(0) && _storage.referralManager != address(0)) {
            IReferralManager(_storage.referralManager).setReferrerCodeFor(accountOwner, referralCode);
        }
        LibOrderBook.placePositionOrder(
            _storage,
            _blockTimestamp(),
            subAccountId,
            collateralAmount,
            size,
            price,
            profitTokenId,
            flags,
            deadline,
            extra
        );
    }

function placeWithdrawalOrder(
        bytes32 subAccountId,
        uint96 rawAmount, // erc20.decimals
        uint8 profitTokenId,
        bool isProfit
    ) external nonReentrant {
        address accountOwner = subAccountId.getSubAccountOwner();
        address msgSender = _msgSender();
        if (_storage.aggregators[msgSender]) {
            // we trust aggregator
        } else {
            // otherwise only account owner can place order
            require(accountOwner == msgSender, "SND"); // SeNDer is not authorized
        }
        require(rawAmount != 0, "A=0"); // Amount Is Zero
        require(!isProfit, "PFT"); // profit order is not allowed

        uint64 orderId = _storage.nextOrderId++;
        bytes32[3] memory data = LibOrder.encodeWithdrawalOrder(
            orderId,
            subAccountId,
            rawAmount,
            profitTokenId,
            isProfit,
            _blockTimestamp()
        );
        _storage.orders.add(orderId, data);

        emit NewWithdrawalOrder(subAccountId, orderId, rawAmount, profitTokenId, isProfit);
    }

function placeWithdrawalOrder(
        OrderBookStorage storage orderBook,
        WithdrawalOrderParams memory orderParams,
        uint64 blockTimestamp
    ) external {
        LibOrderBook._validateCollateral(orderBook, orderParams.tokenAddress);
        if (orderParams.lastConsumedToken != address(0)) {
            LibOrderBook._validateCollateral(orderBook, orderParams.lastConsumedToken);
        }
        if (orderParams.withdrawSwapToken != address(0)) {
            LibOrderBook._validateCollateral(orderBook, orderParams.withdrawSwapToken);
        }
        require(orderParams.rawAmount != 0, "Zero amount");
        require(orderParams.withdrawSwapSlippage <= 1e18, "withdrawSwapSlippage too large");
        (address withdrawAccount, ) = LibCodec.decodePositionId(orderParams.positionId);
        uint64 newOrderId = orderBook.nextOrderId++;
        uint64 gasFeeGwei = LibOrderBook._orderGasFeeGwei(orderBook);
        LibOrderBook._deductGasFee(orderBook, withdrawAccount, gasFeeGwei);
        OrderData memory orderData = LibOrder.encodeWithdrawalOrder(
            orderParams,
            newOrderId,
            blockTimestamp,
            withdrawAccount,
            gasFeeGwei
        );
        LibOrderBook._appendOrder(orderBook, orderData);
        emit IOrderBook.NewWithdrawalOrder(withdrawAccount, newOrderId, orderParams);
    }

function placeWithdrawalOrder(
        WithdrawalOrderParams memory orderParams
    ) external payable whenNotPaused(OrderType.WithdrawalOrder) updateSequence {
        (address positionAccount, ) = LibCodec.decodePositionId(orderParams.positionId);
        if (_isDelegator(msg.sender)) {
            // pass
        } else {
            require(positionAccount == msg.sender, "Not authorized");
        }
        LibOrderBook2.placeWithdrawalOrder(_storage, orderParams, _blockTimestamp());
    }

function redeemMuxToken(
        OrderBookStorage storage _storage,
        address trader,
        uint8 tokenId,
        uint96 muxTokenAmount
    ) external {
        Asset memory asset = _storage.pool.getAssetInfo(tokenId);
        _transferIn(_storage, trader, asset.muxTokenAddress, address(_storage.pool), muxTokenAmount);
        _storage.pool.redeemMuxToken(trader, tokenId, muxTokenAmount);
    }

function redeemMuxToken(uint8 tokenId, uint96 muxTokenAmount) external {
        address trader = _msgSender();
        LibOrderBook.redeemMuxToken(_storage, trader, tokenId, muxTokenAmount);
    }

function redeemMuxToken(
        address trader,
        uint8 tokenId,
        uint96 muxTokenAmount // NOTE: OrderBook SHOULD transfer muxTokenAmount to LiquidityPool
    ) external onlyOrderBook {
        LibLiquidity.redeemMuxToken(_storage, trader, tokenId, muxTokenAmount);
        emit RedeemMuxToken(trader, tokenId, muxTokenAmount);
        _updateSequence();
    }

function redeemMuxToken(
        LiquidityPoolStorage storage _storage,
        address trader,
        uint8 tokenId,
        uint96 muxTokenAmount // NOTE: OrderBook SHOULD transfer muxTokenAmount to LiquidityPool
    ) external {
        require(trader != address(0), "T=0"); // Trader address is zero
        require(_hasAsset(_storage, tokenId), "LST"); // the asset is not LiSTed
        require(muxTokenAmount != 0, "A=0"); // Amount Is Zero
        Asset storage token = _storage.assets[tokenId];
        require(token.isEnabled(), "ENA"); // the token is temporarily not ENAbled
        if (token.isStable()) {
            require(token.isStrictStable(), "STR"); // only STRict stable coins and un-stable coins are supported
        }
        require(token.spotLiquidity >= muxTokenAmount, "LIQ"); // insufficient LIQuidity
        uint256 rawAmount = token.toRaw(muxTokenAmount);
        token.spotLiquidity -= muxTokenAmount;
        token.transferOut(trader, rawAmount, _storage.weth, _storage.nativeUnwrapper);
    }

function withdrawAllCollateral(bytes32 subAccountId) external {
        require(subAccountId.getSubAccountOwner() == _msgSender(), "SND"); // SeNDer is not authorized
        _storage.pool.withdrawAllCollateral(subAccountId);
    }

function withdrawAllCollateral(bytes32 subAccountId) external onlyOrderBook {
        LibSubAccount.DecodedSubAccountId memory decoded = subAccountId.decodeSubAccountId();
        SubAccount storage subAccount = _storage.accounts[subAccountId];
        require(subAccount.size == 0, "S>0"); // position Size should be Zero
        require(subAccount.collateral > 0, "C=0"); // Collateral Is Zero

        Asset storage asset = _storage.assets[decoded.assetId];
        Asset storage collateral = _storage.assets[decoded.collateralId];
        require(asset.isEnabled(), "ENA"); // the token is temporarily not ENAbled
        require(collateral.isEnabled(), "ENA"); // the token is temporarily not ENAbled
        uint96 wadAmount = subAccount.collateral;
        uint256 rawAmount = collateral.toRaw(wadAmount);
        subAccount.collateral = 0;
        collateral.transferOut(decoded.account, rawAmount, _storage.weth, _storage.nativeUnwrapper);
        emit WithdrawCollateral(subAccountId, decoded.account, decoded.collateralId, rawAmount, wadAmount);
        _updateSequence();
    }

function withdrawAllCollateral(
        OrderBookStorage storage orderBook,
        WithdrawAllOrderParams memory orderParams
    ) external {
        require(
            LibOrderBook._isPositionAccountFullyClosed(orderBook, orderParams.positionId),
            "Position account is not fully closed"
        );
        IFacetPositionAccount(orderBook.mux3Facet).withdrawAll(
            IFacetPositionAccount.WithdrawAllArgs({
                positionId: orderParams.positionId,
                isUnwrapWeth: orderParams.isUnwrapWeth,
                // OrderBook.withdrawAll can not support swap. because OrderBook.withdrawAll is not called by broker,
                // so there is no reference prices.
                withdrawSwapToken: address(0),
                withdrawSwapSlippage: 0
            })
        );
    }

function withdrawAllCollateral(
        WithdrawAllOrderParams memory orderParams
    ) external payable nonReentrant whenNotPaused(OrderType.WithdrawalOrder) updateSequence {
        (address positionAccount, ) = LibCodec.decodePositionId(orderParams.positionId);
        if (_isDelegator(msg.sender)) {
            // pass
        } else {
            require(positionAccount == msg.sender, "Not authorized");
        }
        LibOrderBook2.withdrawAllCollateral(_storage, orderParams);
    }

function depositGas(OrderBookStorage storage orderBook, uint256 amount, address account) external {
        _transferIn(orderBook, orderBook.weth, amount);
        orderBook.gasBalances[account] += amount;
    }

function depositGas(address account, uint256 amount) external payable nonReentrant {
        if (_isDelegator(msg.sender)) {
            // pass
        } else {
            require(account == msg.sender, "Not authorized");
        }
        LibOrderBook.depositGas(_storage, amount, account);
    }

function donateLiquidity(
        OrderBookStorage storage orderBook,
        address poolAddress,
        address collateralAddress,
        uint256 rawAmount // token.decimals
    ) external {
        require(rawAmount != 0, "Zero amount");
        LibOrderBook._validateCollateral(orderBook, collateralAddress);
        LibOrderBook._validatePool(orderBook, poolAddress);
        LibOrderBook._transferIn(orderBook, collateralAddress, rawAmount);
        LibOrderBook._transferOut(orderBook, collateralAddress, poolAddress, rawAmount, false);
        ICollateralPool(poolAddress).receiveFee(collateralAddress, rawAmount);
    }

function donateLiquidity(
        address poolAddress,
        address collateralAddress,
        uint256 rawAmount // token.decimals
    ) external updateSequence {
        require(_isFeeDonator(msg.sender), "Not authorized");
        LibOrderBook.donateLiquidity(_storage, poolAddress, collateralAddress, rawAmount);
    }

function fillAdlOrder(
        OrderBookStorage storage orderBook,
        bytes32 positionId,
        bytes32 marketId,
        address lastConsumedToken,
        bool isWithdrawAllIfEmpty,
        bool isUnwrapWeth
    ) external returns (uint256 tradingPrice) {
        // pre-check
        require(IFacetReader(orderBook.mux3Facet).isDeleverageAllowed(positionId, marketId), "ADL safe");
        // close all
        uint256 size = 0;
        {
            PositionReader memory position = IFacetReader(orderBook.mux3Facet).getPositionAccount(positionId, marketId);
            for (uint256 i = 0; i < position.pools.length; i++) {
                size += position.pools[i].size;
            }
        }
        IFacetClose.ClosePositionResult memory result = IFacetClose(orderBook.mux3Facet).closePosition(
            IFacetClose.ClosePositionArgs({
                positionId: positionId,
                marketId: marketId,
                size: size,
                lastConsumedToken: lastConsumedToken,
                isUnwrapWeth: isUnwrapWeth
            })
        );
        tradingPrice = result.tradingPrice;
        {
            (address positionOwner, ) = LibCodec.decodePositionId(positionId);
            emit IOrderBook.FillAdlOrder(
                positionOwner,
                AdlOrderParams({
                    positionId: positionId,
                    marketId: marketId,
                    size: size,
                    price: tradingPrice,
                    isUnwrapWeth: isUnwrapWeth
                })
            );
        }
        // is the position completely closed
        if (_isPositionAccountFullyClosed(orderBook, positionId)) {
            // auto withdraw, equivalent to POSITION_WITHDRAW_ALL_IF_EMPTY
            if (isWithdrawAllIfEmpty) {
                // default values of isUnwrapWeth, withdrawSwapToken, withdrawSwapSlippage
                // so that mux3 looks like mux1
                IFacetPositionAccount(orderBook.mux3Facet).withdrawAll(
                    IFacetPositionAccount.WithdrawAllArgs({
                        positionId: positionId,
                        isUnwrapWeth: isUnwrapWeth,
                        withdrawSwapToken: address(0),
                        withdrawSwapSlippage: 0
                    })
                );
            }
        }

        // cancel activated tp/sl orders
        _cancelActivatedTpslOrders(orderBook, positionId, marketId);
        return tradingPrice;
    }

function fillLiquidityOrder(
        OrderBookStorage storage _storage,
        uint32 blockTimestamp,
        uint96 assetPrice,
        uint96 mlpPrice,
        uint96 currentAssetValue,
        uint96 targetAssetValue,
        bytes32[3] memory orderData
    ) external returns (uint256 outAmount) {
        LiquidityOrder memory order = orderData.decodeLiquidityOrder();
        require(blockTimestamp >= order.placeOrderTime + _storage.liquidityLockPeriod, "LCK"); // mlp token is LoCKed
        uint96 rawAmount = order.rawAmount;
        if (order.isAdding) {
            IERC20Upgradeable collateral = IERC20Upgradeable(_storage.pool.getAssetAddress(order.assetId));
            collateral.safeTransfer(address(_storage.pool), rawAmount);
            outAmount = _storage.pool.addLiquidity(
                order.account,
                order.assetId,
                rawAmount,
                assetPrice,
                mlpPrice,
                currentAssetValue,
                targetAssetValue
            );
        } else {
            _storage.mlp.safeTransfer(address(_storage.pool), rawAmount);
            outAmount = _storage.pool.removeLiquidity(
                order.account,
                rawAmount,
                order.assetId,
                assetPrice,
                mlpPrice,
                currentAssetValue,
                targetAssetValue
            );
        }
    }

function fillLiquidityOrder(
        uint64 orderId,
        uint96 assetPrice,
        uint96 mlpPrice,
        uint96 currentAssetValue,
        uint96 targetAssetValue
    ) external onlyBroker whenLiquidityOrderEnabled nonReentrant {
        require(_storage.orders.contains(orderId), "OID"); // can not find this OrderID
        bytes32[3] memory orderData = _storage.orders.get(orderId);
        _storage.orders.remove(orderId);
        LiquidityOrder memory order = LibOrder.decodeLiquidityOrder(orderData);
        if (_storage.callbackWhitelist[order.account]) {
            bool isValid;
            try
                ILiquidityCallback(order.account).beforeFillLiquidityOrder{ gas: _callbackGasLimit() }(
                    order,
                    assetPrice,
                    mlpPrice,
                    currentAssetValue,
                    targetAssetValue
                )
            returns (bool _isValid) {
                isValid = _isValid;
            } catch {
                isValid = false;
            }
            if (!isValid) {
                _cancelLiquidityOrder(order);
                emit CancelOrder(orderId, LibOrder.getOrderType(orderData), orderData);
                return;
            }
        }
        OrderType orderType = LibOrder.getOrderType(orderData);
        require(orderType == OrderType.LiquidityOrder, "TYP"); // order TYPe mismatch
        uint256 outAmount;
        if (order.rawAmount != 0) {
            outAmount = LibOrderBook.fillLiquidityOrder(
                _storage,
                _blockTimestamp(),
                assetPrice,
                mlpPrice,
                currentAssetValue,
                targetAssetValue,
                orderData
            );
        } else {
            require(_storage.callbackWhitelist[order.account], "NCB");
            outAmount = 0;
        }
        if (_storage.callbackWhitelist[order.account]) {
            ILiquidityCallback(order.account).afterFillLiquidityOrder{ gas: _callbackGasLimit() }(
                order,
                outAmount,
                assetPrice,
                mlpPrice,
                currentAssetValue,
                targetAssetValue
            );
        }
        emit FillOrder(orderId, orderType, orderData);
    }

function fillLiquidityOrder(
        OrderBookStorage storage orderBook,
        uint64 orderId,
        IFacetOpen.ReallocatePositionArgs[] memory reallocateArgs,
        uint64 blockTimestamp
    ) external returns (uint256 outAmount) {
        require(orderBook.orders.contains(orderId), "No such orderId");
        OrderData memory orderData = orderBook.orderData[orderId];
        LibOrderBook._removeOrder(orderBook, orderData);
        require(orderData.orderType == OrderType.LiquidityOrder, "Order type mismatch");
        // fill
        LiquidityOrderParams memory orderParams = LibOrder.decodeLiquidityOrder(orderData);
        uint256 lockPeriod = LibOrderBook._liquidityLockPeriod(orderBook);
        require(blockTimestamp >= orderData.placeOrderTime + lockPeriod, "Liquidity order is under lock period");
        uint256 lpPrice;
        uint256 collateralPrice;
        if (orderParams.isAdding) {
            require(!LibOrderBook._isPoolDraining(orderParams.poolAddress), "Draining pool");
            (outAmount, lpPrice, collateralPrice) = _fillAddLiquidityOrder(
                orderBook,
                orderData,
                orderParams,
                reallocateArgs
            );
        } else {
            (outAmount, lpPrice, collateralPrice) = _fillRemoveLiquidityOrder(
                orderBook,
                orderData,
                orderParams,
                reallocateArgs
            );
        }
        emit IOrderBook.FillOrder(orderData.account, orderId, orderData);
        // gas
        LibOrderBook._payGasFee(orderBook, orderData, msg.sender);
        _runLiquidityCallback(orderBook, orderId, orderData, orderParams, outAmount, lpPrice, collateralPrice);
    }

function fillLiquidityOrder(
        uint64 orderId,
        IFacetOpen.ReallocatePositionArgs[] memory reallocateArgs
    )
        external
        onlyRole(BROKER_ROLE)
        whenNotPaused(OrderType.LiquidityOrder)
        nonReentrant
        updateSequence
        returns (uint256 outAmount)
    {
        return LibOrderBook2.fillLiquidityOrder(_storage, orderId, reallocateArgs, _blockTimestamp());
    }

function fillPositionOrder(
        uint64 orderId,
        uint96 collateralPrice,
        uint96 assetPrice,
        uint96 profitAssetPrice // only used when !isLong
    ) external onlyBroker whenPositionOrderEnabled nonReentrant {
        require(_storage.orders.contains(orderId), "OID"); // can not find this OrderID
        bytes32[3] memory orderData = _storage.orders.get(orderId);
        _storage.orders.remove(orderId);
        OrderType orderType = LibOrder.getOrderType(orderData);
        require(orderType == OrderType.PositionOrder, "TYP"); // order TYPe mismatch

        PositionOrder memory order = orderData.decodePositionOrder();
        require(_blockTimestamp() <= _positionOrderDeadline(order), "EXP"); // EXPired
        uint96 tradingPrice;
        if (order.isOpenPosition()) {
            tradingPrice = LibOrderBook.fillOpenPositionOrder(
                _storage,
                _blockTimestamp(),
                orderId,
                collateralPrice,
                assetPrice,
                order
            );
        } else {
            tradingPrice = LibOrderBook.fillClosePositionOrder(
                _storage,
                _blockTimestamp(),
                orderId,
                collateralPrice,
                assetPrice,
                profitAssetPrice,
                order
            );
        }
        // price check
        if (!order.isMarketOrder()) {
            // open,long      0,0   0,1   1,1   1,0
            // limitOrder     <=    >=    <=    >=
            // triggerOrder   >=    <=    >=    <=
            bool isLess = (order.subAccountId.isLong() == order.isOpenPosition());
            if (order.isTriggerOrder()) {
                isLess = !isLess;
            }
            if (isLess) {
                require(tradingPrice <= order.price, "LMT"); // LiMiTed by limitPrice
            } else {
                require(tradingPrice >= order.price, "LMT"); // LiMiTed by limitPrice
            }
        }

        emit FillOrder(orderId, orderType, orderData);
    }

function fillPositionOrder(
        OrderBookStorage storage orderBook,
        uint64 orderId,
        uint64 blockTimestamp
    ) external returns (uint256 tradingPrice) {
        require(orderBook.orders.contains(orderId), "No such orderId");
        OrderData memory orderData = orderBook.orderData[orderId];
        _removeOrder(orderBook, orderData);
        require(orderData.orderType == OrderType.PositionOrder, "Order type mismatch");
        PositionOrderParams memory orderParams = LibOrder.decodePositionOrder(orderData);
        uint256 deadline = MathUpgradeable
            .min(orderData.placeOrderTime + _positionOrderTimeout(orderBook, orderParams), orderParams.expiration)
            .toUint64();
        require(blockTimestamp <= deadline, "Order expired");
        // fill
        if (LibOrder.isOpenPosition(orderParams)) {
            tradingPrice = _fillOpenPositionOrder(orderBook, orderParams, blockTimestamp);
        } else {
            tradingPrice = _fillClosePositionOrder(orderBook, orderParams, orderId);
        }
        // price check
        // open,long      0,0   0,1   1,1   1,0
        // limitOrder     <=    >=    <=    >=
        // triggerOrder   >=    <=    >=    <=
        bool isLong = _isMarketLong(orderBook, orderParams.marketId);
        bool isLess = (isLong == LibOrder.isOpenPosition(orderParams));
        if (LibOrder.isTriggerOrder(orderParams)) {
            isLess = !isLess;
        }
        if (isLess) {
            require(tradingPrice <= orderParams.limitPrice, "limitPrice");
        } else {
            require(tradingPrice >= orderParams.limitPrice, "limitPrice");
        }
        emit IOrderBook.FillOrder(orderData.account, orderId, orderData);
        // gas
        _payGasFee(orderBook, orderData, msg.sender);
    }

function fillPositionOrder(
        uint64 orderId
    )
        external
        onlyRole(BROKER_ROLE)
        nonReentrant
        whenNotPaused(OrderType.PositionOrder)
        updateSequence
        returns (uint256 tradingPrice)
    {
        return LibOrderBook.fillPositionOrder(_storage, orderId, _blockTimestamp());
    }

function fillRebalanceOrder(
        uint64 orderId,
        uint96 price0,
        uint96 price1
    ) external onlyBroker whenLiquidityOrderEnabled nonReentrant {
        require(_storage.orders.contains(orderId), "OID"); // can not find this OrderID
        bytes32[3] memory orderData = _storage.orders.get(orderId);
        _storage.orders.remove(orderId);
        OrderType orderType = LibOrder.getOrderType(orderData);
        require(orderType == OrderType.RebalanceOrder, "TYP"); // order TYPe mismatch

        RebalanceOrder memory order = orderData.decodeRebalanceOrder();
        _storage.pool.rebalance(
            order.rebalancer,
            order.tokenId0,
            order.tokenId1,
            order.rawAmount0,
            order.maxRawAmount1,
            order.userData,
            price0,
            price1
        );

        emit FillOrder(orderId, orderType, orderData);
    }

function fillRebalanceOrder(OrderBookStorage storage orderBook, uint64 orderId) external {
        require(orderBook.orders.contains(orderId), "No such orderId");
        OrderData memory orderData = orderBook.orderData[orderId];
        LibOrderBook._removeOrder(orderBook, orderData);
        require(orderData.orderType == OrderType.RebalanceOrder, "Order type mismatch");
        RebalanceOrderParams memory orderParams = LibOrder.decodeRebalanceOrder(orderData);
        ICollateralPool(orderParams.poolAddress).rebalance(
            orderData.account,
            orderParams.token0,
            orderParams.rawAmount0,
            orderParams.maxRawAmount1,
            orderParams.userData
        );
        emit IOrderBook.FillOrder(orderData.account, orderId, orderData);
    }

function fillRebalanceOrder(
        uint64 orderId
    ) external onlyRole(BROKER_ROLE) nonReentrant whenNotPaused(OrderType.RebalanceOrder) updateSequence {
        LibOrderBook2.fillRebalanceOrder(_storage, orderId);
    }

function fillWithdrawalOrder(
        uint64 orderId,
        uint96 collateralPrice,
        uint96 assetPrice,
        uint96 profitAssetPrice // only used when !isLong
    ) external onlyBroker nonReentrant {
        require(_storage.orders.contains(orderId), "OID"); // can not find this OrderID
        bytes32[3] memory orderData = _storage.orders.get(orderId);
        _storage.orders.remove(orderId);
        OrderType orderType = LibOrder.getOrderType(orderData);
        require(orderType == OrderType.WithdrawalOrder, "TYP"); // order TYPe mismatch

        WithdrawalOrder memory order = orderData.decodeWithdrawalOrder();
        require(_blockTimestamp() <= order.placeOrderTime + _storage.marketOrderTimeout, "EXP"); // EXPired
        require(!order.isProfit, "PFT"); // profit order is not allowed
        _storage.pool.withdrawCollateral(order.subAccountId, order.rawAmount, collateralPrice, assetPrice);

        emit FillOrder(orderId, orderType, orderData);
    }

function fillWithdrawalOrder(OrderBookStorage storage orderBook, uint64 orderId, uint64 blockTimestamp) external {
        require(orderBook.orders.contains(orderId), "No such orderId");
        OrderData memory orderData = orderBook.orderData[orderId];
        LibOrderBook._removeOrder(orderBook, orderData);
        require(orderData.orderType == OrderType.WithdrawalOrder, "Order type mismatch");
        WithdrawalOrderParams memory orderParams = LibOrder.decodeWithdrawalOrder(orderData);
        uint64 deadline = orderData.placeOrderTime + LibOrderBook._withdrawalOrderTimeout(orderBook);
        require(blockTimestamp <= deadline, "Order expired");
        // fill
        IFacetPositionAccount(orderBook.mux3Facet).withdraw(
            IFacetPositionAccount.WithdrawArgs({
                positionId: orderParams.positionId,
                collateralToken: orderParams.tokenAddress,
                amount: orderParams.rawAmount,
                lastConsumedToken: orderParams.lastConsumedToken,
                isUnwrapWeth: orderParams.isUnwrapWeth,
                withdrawSwapToken: orderParams.withdrawSwapToken,
                withdrawSwapSlippage: orderParams.withdrawSwapSlippage
            })
        );
        emit IOrderBook.FillOrder(orderData.account, orderId, orderData);
        // gas
        LibOrderBook._payGasFee(orderBook, orderData, msg.sender);
    }

