function _placeOpenPositionOrder(
        OrderBookStorage storage _storage,
        uint32 blockTimestamp,
        bytes32 subAccountId,
        uint96 collateralAmount, // erc20.decimals
        uint96 size, // 1e18
        uint96 price, // 1e18
        uint8 flags,
        uint32 deadline, // 1e0
        PositionOrderExtra memory extra
    ) private {
        // add order
        uint64 orderId = _placePositionOrder(
            _storage,
            blockTimestamp,
            deadline,
            PositionOrder({
                id: 0, // ignored
                subAccountId: subAccountId,
                collateral: collateralAmount,
                size: size,
                price: price,
                profitTokenId: 0, // open-position-order does not have a profitTokenId
                flags: flags,
                placeOrderTime: 0, // ignored
                expire10s: 0 // ignored
            })
        );
        // fetch collateral
        if (collateralAmount > 0) {
            address accountOwner = subAccountId.getSubAccountOwner();
            uint8 collateralId = subAccountId.getSubAccountCollateralId();
            address collateralAddress = _storage.pool.getAssetAddress(collateralId);
            _transferIn(_storage, accountOwner, collateralAddress, address(this), collateralAmount);
        }
        if ((flags & LibOrder.POSITION_TPSL_STRATEGY) != 0) {
            // tp/sl strategy
            require((extra.tpPrice > 0 || extra.slPrice > 0), "TPSL"); // TP/SL strategy need tpPrice and/or slPrice
            require(extra.tpslDeadline > blockTimestamp, "D<0"); // Deadline is earlier than now
            require((extra.tpslDeadline - blockTimestamp) / 10 <= type(uint24).max, "DTL"); // Deadline is Too Large
            _storage.positionOrderExtras[orderId] = extra;
            emit NewPositionOrderExtra(
                subAccountId,
                orderId,
                collateralAmount,
                size,
                price,
                0 /* profitTokenId */,
                flags,
                deadline,
                extra
            );
        }
    }

function _placeOpenPositionOrder(
        OrderBookStorage storage orderBook,
        PositionOrderParams memory orderParams,
        uint64 blockTimestamp
    ) private {
        require(orderParams.withdrawUsd == 0, "WithdrawUsd is not suitable for open-position");
        require(orderParams.withdrawSwapToken == address(0), "WithdrawSwapToken is not suitable for open-position");
        require(orderParams.withdrawSwapSlippage == 0, "WithdrawSwapSlippage is not suitable for open-position");
        // fetch collateral
        if (orderParams.collateralToken != address(0)) {
            _validateCollateral(orderBook, orderParams.collateralToken);
            if (orderParams.collateralAmount > 0) {
                // deposit collateral
                _transferIn(orderBook, orderParams.collateralToken, orderParams.collateralAmount);
            }
        }
        // tp/sl strategy
        if (orderParams.tpPriceDiff > 0 || orderParams.slPriceDiff > 0) {
            require(orderParams.tpslExpiration > blockTimestamp, "tpslExpiration is earlier than now");
            uint256 validFlags = POSITION_WITHDRAW_ALL_IF_EMPTY | POSITION_WITHDRAW_PROFIT | POSITION_UNWRAP_ETH;
            require((orderParams.tpslFlags & (~validFlags)) == 0, "Unsupported tpslFlags");
            if (orderParams.tpslWithdrawSwapToken != address(0)) {
                _validateCollateral(orderBook, orderParams.tpslWithdrawSwapToken);
            }
            bool isLong = _isMarketLong(orderBook, orderParams.marketId);
            if (isLong) {
                // close a long means sell, sl means limitPrice = tradingPrice * (1 - slPriceDiff)
                require(orderParams.slPriceDiff < 1e18, "slPriceDiff too large");
            } else {
                // close a short means buy, tp means limitPrice = tradingPrice * (1 - tpPriceDiff)
                require(orderParams.tpPriceDiff < 1e18, "tpPriceDiff too large");
            }
            require(orderParams.tpslWithdrawSwapSlippage <= 1e18, "tpslWithdrawSwapSlippage too large");
        }
        // add order
        uint64 gasFeeGwei = _orderGasFeeGwei(orderBook);
        _appendPositionOrder(orderBook, orderParams, blockTimestamp, gasFeeGwei);
    }

function _placeClosePositionOrder(
        OrderBookStorage storage _storage,
        uint32 blockTimestamp,
        bytes32 subAccountId,
        uint96 collateralAmount, // erc20.decimals
        uint96 size, // 1e18
        uint96 price, // 1e18
        uint8 profitTokenId,
        uint8 flags,
        uint32 deadline, // 1e0
        PositionOrderExtra memory extra
    ) private {
        if ((flags & LibOrder.POSITION_TPSL_STRATEGY) != 0) {
            // tp/sl strategy
            require(price == 0, "P!0"); // use extra.tpPrice and extra.slPrice instead
            require(collateralAmount == 0, "C!0"); // tp/sl strategy only supports POSITION_WITHDRAW_ALL_IF_EMPTY
            require(profitTokenId == 0, "T!0"); // use extra.tpProfitTokenId instead
            require((flags & LibOrder.POSITION_MARKET_ORDER) == 0, "MKT"); // tp/sl strategy does not support MarKeT order
            require(extra.tpPrice > 0 && extra.slPrice > 0, "TPSL"); // tp/sl strategy need tpPrice and slPrice. otherwise use POSITION_TRIGGER_ORDER instead
            require(extra.tpslDeadline > blockTimestamp, "D<0"); // Deadline is earlier than now
            require((extra.tpslDeadline - blockTimestamp) / 10 <= type(uint24).max, "DTL"); // Deadline is Too Large
            _placeTpslOrdersWhenClose(_storage, blockTimestamp, subAccountId, size, extra);
        } else {
            // normal close-position-order
            if (flags & LibOrder.POSITION_SHOULD_REACH_MIN_PROFIT != 0) {
                // POSITION_MUST_PROFIT is only available if asset.minProfitTime > 0
                uint8 assetId = subAccountId.getSubAccountAssetId();
                Asset memory asset = _storage.pool.getAssetInfo(assetId);
                require(asset.minProfitTime > 0, "MPT"); // asset MinProfitTime is 0
            }
            _placePositionOrder(
                _storage,
                blockTimestamp,
                deadline,
                PositionOrder({
                    id: 0, // ignored
                    subAccountId: subAccountId,
                    collateral: collateralAmount,
                    size: size,
                    price: price,
                    profitTokenId: profitTokenId,
                    flags: flags,
                    placeOrderTime: 0, // ignored
                    expire10s: 0 // ignored
                })
            );
        }
    }

function _placeClosePositionOrder(
        OrderBookStorage storage orderBook,
        PositionOrderParams memory orderParams,
        uint64 blockTimestamp
    ) private {
        require(orderParams.collateralToken == address(0) && orderParams.collateralAmount == 0, "Use withdraw instead");
        if (orderParams.withdrawSwapToken != address(0)) {
            _validateCollateral(orderBook, orderParams.withdrawSwapToken);
        }
        require(orderParams.withdrawSwapSlippage <= 1e18, "withdrawSwapSlippage too large");
        // tp/sl strategy is not supported
        require(
            orderParams.tpPriceDiff == 0 &&
                orderParams.slPriceDiff == 0 &&
                orderParams.tpslExpiration == 0 &&
                orderParams.tpslFlags == 0 &&
                orderParams.tpslWithdrawSwapToken == address(0) &&
                orderParams.tpslWithdrawSwapSlippage == 0,
            "Place multiple close-position orders instead"
        );
        // add order
        uint64 gasFeeGwei = _orderGasFeeGwei(orderBook);
        _appendPositionOrder(orderBook, orderParams, blockTimestamp, gasFeeGwei);
    }

function _transferIn(
        OrderBookStorage storage _storage,
        address trader,
        address tokenAddress,
        address recipient,
        uint256 rawAmount
    ) internal {
        if (tokenAddress == address(_storage.weth)) {
            require(msg.value > 0 && msg.value == rawAmount, "VAL"); // transaction VALue SHOULD equal to rawAmount
            _storage.weth.deposit{ value: rawAmount }();
            if (recipient != address(this)) {
                _storage.weth.transfer(recipient, rawAmount);
            }
        } else {
            require(msg.value == 0, "VAL"); // transaction VALue SHOULD be 0
            IERC20Upgradeable(tokenAddress).safeTransferFrom(trader, recipient, rawAmount);
        }
    }

function _transferIn(OrderBookStorage storage orderBook, address tokenAddress, uint256 rawAmount) internal {
        uint256 oldBalance = orderBook.previousTokenBalance[tokenAddress];
        uint256 newBalance = IERC20Upgradeable(tokenAddress).balanceOf(address(this));
        require(newBalance >= oldBalance, "Token balance decreased");
        uint256 realRawAmount = newBalance - oldBalance;
        require(realRawAmount >= rawAmount, "Token balance not enough");
        orderBook.previousTokenBalance[tokenAddress] = newBalance;
    }

function addLiquidity(AddLiquidityParams calldata params)
        external
        nonReentrant
        checkTwoCrypto(params.twoCrypto)
        checkDeadline(params.deadline)
        returns (uint256 liquidity)
    {
        TwoCrypto twoCrypto = params.twoCrypto;
        address pt = twoCrypto.coins(PT_INDEX);
        address underlying = twoCrypto.coins(TARGET_INDEX);

        SafeTransferLib.safeTransferFrom(pt, msg.sender, address(this), params.principal);
        SafeTransferLib.safeTransferFrom(underlying, msg.sender, address(this), params.shares);

        approveIfNeeded(pt, twoCrypto.unwrap());
        approveIfNeeded(underlying, twoCrypto.unwrap());
        liquidity = twoCrypto.add_liquidity({
            amount0: params.shares,
            amount1: params.principal,
            minLiquidity: params.minLiquidity,
            receiver: params.receiver
        });

        Events.emitZapAddLiquidity({
            by: msg.sender,
            receiver: params.receiver,
            twoCrypto: twoCrypto,
            liquidity: liquidity,
            shares: params.shares,
            principal: params.principal
        });
    }

function addLiquidityOneToken(AddLiquidityOneTokenParams calldata params)
        external
        payable
        nonReentrant
        checkTwoCrypto(params.twoCrypto)
        checkDeadline(params.deadline)
        returns (uint256 liquidity, uint256 principal)
    {
        TwoCrypto twoCrypto = params.twoCrypto;
        PrincipalToken principalToken = PrincipalToken(twoCrypto.coins(PT_INDEX));
        address underlying = twoCrypto.coins(TARGET_INDEX);

        uint256 shares = _deposit(
            underlying, principalToken.i_asset().asAddr(), params.tokenIn, params.amountIn, address(this), msg.sender
        );

        (liquidity, principal) = _addLiquidityOneUnderlying(
            AddLiquidityOneUnderlyingParams({
                twoCrypto: twoCrypto,
                principalToken: principalToken,
                underlying: underlying,
                shares: shares,
                minYt: params.minYt,
                minLiquidity: params.minLiquidity,
                receiver: params.receiver
            })
        );

        Events.emitZapAddLiquidityOneToken({
            by: msg.sender,
            receiver: params.receiver,
            twoCrypto: twoCrypto,
            liquidity: liquidity,
            ytOut: principal,
            tokenIn: params.tokenIn,
            amountIn: params.amountIn
        });
    }

function combine(uint256 principal, address receiver) external returns (uint256) {
        return combine(principal, receiver, "");
    }

function combine(uint256 principal, address receiver, bytes memory data)
        public
        nonReentrant
        settleIfExpired
        returns (uint256)
    {
        address[] memory m = ModuleAccessor.read(s_modules);
        Snapshot memory snapshot = s_snapshot;

        FeePcts feePcts = FeeModule(m.unsafeGet(FEE_MODULE_INDEX)).getFeePcts();
        uint256 ytBalance = i_yt.balanceOf(msg.sender);

        (uint256 shares, uint256 fee) = _previewCombine(snapshot, feePcts, principal);

        _writeState(snapshot, feePcts, fee);

        _accrueYield(snapshot, msg.sender, ytBalance);

        // Accrue rewards if any
        TokenReward[] memory rewards = _delegateCallRewardProxy(m);
        _accrueRewards(feePcts, rewards, msg.sender, ytBalance, address(0), 0);

        _uniteWithHook(msg.sender, receiver, shares, principal, data);

        return shares;
    }

function combine(
        PrincipalToken principalToken,
        Token tokenOut,
        uint256 principal,
        address receiver,
        uint256 minAmount
    ) external nonReentrant checkPrincipalToken(principalToken) returns (uint256 amountOut) {
        amountOut =
            _combine({principalToken: principalToken, token: tokenOut, principal: principal, receiver: receiver});
        if (amountOut < minAmount) Errors.Zap_InsufficientTokenOutput.selector.revertWith();

        Events.emitZapUnite({
            by: msg.sender,
            receiver: receiver,
            pt: address(principalToken),
            principal: principal,
            tokenOut: tokenOut,
            amountOut: amountOut
        });
    }

function removeLiquidity(RemoveLiquidityParams calldata params)
        external
        nonReentrant
        checkTwoCrypto(params.twoCrypto)
        checkDeadline(params.deadline)
        returns (uint256 shares, uint256 principal)
    {
        TwoCrypto twoCrypto = params.twoCrypto;

        SafeTransferLib.safeTransferFrom(twoCrypto.unwrap(), msg.sender, address(this), params.liquidity);

        (shares, principal) = twoCrypto.remove_liquidity({
            liquidity: params.liquidity,
            minAmount0: params.minShares,
            minAmount1: params.minPrincipal,
            receiver: params.receiver
        });

        Events.emitZapRemoveLiquidity({
            by: msg.sender,
            receiver: params.receiver,
            twoCrypto: twoCrypto,
            liquidity: params.liquidity,
            shares: shares,
            principal: principal
        });
    }

function swapTokenForPt(SwapTokenParams calldata params)
        external
        payable
        nonReentrant
        checkTwoCrypto(params.twoCrypto)
        checkDeadline(params.deadline)
        returns (uint256 ptOut)
    {
        // At this point, `twoCrypto` is verified as an instance deployed from our factory
        TwoCrypto twoCrypto = params.twoCrypto;
        PrincipalToken principalToken = PrincipalToken(twoCrypto.coins(PT_INDEX));
        address underlying = twoCrypto.coins(TARGET_INDEX);

        // Deposit tokens and get shares
        uint256 shares = _deposit(
            underlying,
            principalToken.i_asset().asAddr(),
            params.tokenIn,
            params.amountIn,
            twoCrypto.unwrap(),
            msg.sender
        );

        // Swap shares for PT using TwoCrypto
        ptOut =
            twoCrypto.exchange_received({i: TARGET_INDEX, j: PT_INDEX, dx: shares, minDy: 0, receiver: params.receiver});

        if (ptOut < params.minPrincipal) Errors.Zap_InsufficientPrincipalTokenOutput.selector.revertWith();

        Events.emitZapSwap({
            by: msg.sender,
            receiver: params.receiver,
            twoCrypto: twoCrypto,
            tokenIn: params.tokenIn,
            amountIn: params.amountIn,
            tokenOut: Token.wrap(address(principalToken)),
            amountOut: ptOut
        });
    }

