function liquidate(
        address[] calldata accounts,
        address collateralToken
    ) external nonReentrant {
        uint256 numAccounts = accounts.length;
        // `debtAmounts` array is empty since the max amount possible
        // will be liquidated.
        uint256[] memory debtAmounts = new uint256[](numAccounts);
        
        _liquidate(
            debtAmounts,
            msg.sender,
            accounts,
            collateralToken,
            numAccounts,
            false
        );
    }

function liquidateExact(
        uint256[] calldata debtAmounts,
        address[] calldata accounts,
        address collateralToken
    ) external nonReentrant {
        uint256 numAccounts = accounts.length;
        if (numAccounts != debtAmounts.length) {
            _revert(_INVALID_PARAMETER_SELECTOR);
        }

        _liquidate(
            debtAmounts,
            msg.sender,
            accounts,
            collateralToken,
            numAccounts,
            true
        );
    }

function seize(
        uint256[] calldata liquidatedShares,
        address liquidator,
        address[] calldata accounts
    ) external nonReentrant {
        // Fails if seizure not allowed.
        marketManager.canSeize(address(this), msg.sender);

        // We know that `accounts` and `liquidatedShares` arrays are the same
        // length since we validate it inside the cToken getting debt repaid
        // as part of this liquidation.

        uint256 numAccounts = accounts.length;
        uint256 totalShares;
        uint256 shares;
        address account;

        for (uint256 i; i < numAccounts; ++i) {
            shares = liquidatedShares[i];
            // If theres no shares to liquidate for this account can
            // skip them.
            if (shares == 0) {
                continue;
            }

            account = accounts[i];

            // Execute any prior liquidation action.
            _beforeLiqAction(shares, liquidator, account);
            totalShares += shares;

            // Update `account` collateral posted invariant and transfer
            // their collateral shares.
            collateralPosted[account] = collateralPosted[account] - shares;
            emit CollateralUpdated(shares, false, account);

            // Transfer liquidated shares from `account` to `liquidator`.
            _transferFromWithoutAllowance(account, liquidator, shares);
            emit Liquidated(shares, liquidator, account);
        }

        // Update market collateral posted invariant for the liquidated
        // shares.
        marketCollateralPosted = marketCollateralPosted - totalShares;
    }

function borrowForPositionManager(
        uint256 assets,
        address owner,
        IPositionManager.LeverageAction memory action
    ) external nonReentrant {
        if (!marketManager.isPositionManager(msg.sender)) {
            _revert(_UNAUTHORIZED_SELECTOR);
        }

        // Accrue interest if needed.
        // This generally is a redundant check due to interest accrual
        // done inside `checkSlippage` modifier inside position manager
        // contracts, but we keep this check in for invariant
        // protection in the case of a incorrectly implemented contract.
        _accrueIfNeeded();

        // Notifies the Market Manager that a user is taking on more debt,
        // and to pause user redemptions for 20 minutes.
        marketManager.notifyBorrow(address(this), owner);

        _borrow(assets, msg.sender, owner);

        // Callback to Position Manager to execute remaining leverage logic.
        IPositionManager(msg.sender).onBorrow(
            address(this),
            assets,
            owner,
            action
        );

        // Fail if terminal position is not allowed with no additional
        // adjustment.
        marketManager.canBorrow(
            address(this),
            0,
            owner,
            marketOutstandingDebt
        );
    }

function withdrawByPositionManager(
        uint256 assets,
        address owner,
        IPositionManager.DeleverageAction memory action
    ) external nonReentrant {
        // Validate that a position manager is calling.
        if (!marketManager.isPositionManager(msg.sender)) {
            _revert(_UNAUTHORIZED_SELECTOR);
        }

        _accrueIfNeeded();

        // Use up-to-date total assets including any pending vesting via getter.
        uint256 ta = _getTotalAssets();
        uint256 balance = _checkRedemption(assets, owner, ta);
        // No need to check for rounding error, previewWithdraw rounds up.
        uint256 shares = _previewWithdraw(assets, ta);

        _processWithdraw(assets, shares, msg.sender, msg.sender, owner);

        // Process the position manager redemption leg.
        _processPositionManagerRedemption(
            assets,
            shares,
            owner,
            balance,
            action
        );
    }

function _liquidate(
        uint256[] memory debtAmounts,
        address liquidator,
        address[] calldata accounts,
        address collateralToken,
        uint256 numAccounts,
        bool exactAmount
    ) internal {
        // Cannot have debt and collateral in the same token, so can revert
        // immediately if someone tries.
        if (collateralToken == address(this)) {
            _revert(_INVALID_PARAMETER_SELECTOR);
        }

        // Accrue interest if needed.
        _accrueIfNeeded();

        IMarketManager.LiqResult memory result;

        // Fails if liquidation not allowed, trying to repay too much debt
        // will revert.
        (result, debtAmounts) = marketManager.canLiquidate(
            debtAmounts,
            liquidator,
            accounts,
            IMarketManager.LiqAction({
                collateralToken: collateralToken,
                debtToken: address(this),
                numAccounts: numAccounts,
                liquidateExact: exactAmount,
                liquidatedShares: 0,
                debtRepaid: 0,
                badDebt: 0
            })
        );

        SafeTransferLib.safeTransferFrom(
            asset(),
            liquidator,
            address(this),
            result.debtRepaid
        );

        uint80 cachedDebtIndex = uint80(_vestingData >> _BITPOS_DEBT_INDEX);
        uint256 debtAmount;
        uint256 debtOf;
        address account;

        for (uint256 i; i < numAccounts; ++i) {
            // Cache the liquidation repayment amount.
            debtAmount = debtAmounts[i];
            // If theres no debt to repay for this user can
            // skip them.
            if (debtAmount == 0) {
                continue;
            }

            account = accounts[i];

            // Calculate the new `account` outstanding debt, then update the
            // account's debt balance and debt index value.
            // Update the account and market outstanding debt balance data.
            debtOf = debtBalance(account) - debtAmount;
            _setDebtOf(
                account,
                uint176(debtOf),
                cachedDebtIndex
            );
            emit Repay(debtAmount, debtOf, liquidator, account);
        }

        // We need to update marketOutstandingDebt for the total debt repaid
        // by the liquidator, plus the bad debt being realized. We can reuse
        // debtRepaid variable since the original debt repayment value
        // was already used earlier.
        result.debtRepaid += result.badDebtRealized;
        if (marketOutstandingDebt < result.debtRepaid) {
            // We round user debt in favor of the protocol to prevent exchange
            // rate manipulation, as a result in some cases the last user
            // cannot fully repay their debt.
            marketOutstandingDebt = 0;
        } else {
            marketOutstandingDebt =
                uint240(marketOutstandingDebt - result.debtRepaid);
        }

        // Update total assets to recognize that lenders wont be getting
        // `result.badDebtRealized` back due to realized bad debt.
        // Emit corresponding event recognizing bad debt.
        if (result.badDebtRealized > 0) {
            uint256 ta = _totalAssets;
            if (ta < result.badDebtRealized + _BASE_UNDERLYING_RESERVE) {
                revert BorrowableCToken__InsufficientAssetsHeld();
            }
            _totalAssets = ta - result.badDebtRealized;
            emit BadDebtRecognized(result.badDebtRealized, liquidator);
        }

        ICToken(collateralToken).seize(
            result.liquidatedShares,
            liquidator,
            accounts 
        );
    }

function canLiquidate(
        uint256[] memory debtAmounts,
        address liquidator,
        address[] calldata accounts,
        IMarketManager.LiqAction memory action
    ) external returns (
        IMarketManager.LiqResult memory result,
        uint256[] memory
    ) {
        if (liquidationPaused == 2) {
            revert MarketManager__Paused();
        }

        _checkIsToken(action.debtToken);
        _checkIsListedToken(action.collateralToken);
        _checkIsListedToken(action.debtToken);

        (TokenLiqData memory tData, AccountLiqData memory aData) =
            _getLiquidationConfig(action.collateralToken, action.debtToken);

        // Amounts array is empty since the max amount possible
        // will be liquidated.
        result.liquidatedShares = new uint256[](action.numAccounts);
        address cachedAccount;
        address priorAccount;
        for (uint256 i; i < action.numAccounts; ++i) {
            cachedAccount = accounts[i];
            
            // Do not let an account liquidate themselves.
            if (liquidator == cachedAccount) {
                _revert(_UNAUTHORIZED_SELECTOR);
            }

            // Liquidators MUST sort the token addresses offchain from
            // smallest to largest to validate there are no duplicate
            // liquidations.
            if (priorAccount >= cachedAccount) {
                _revert(_UNAUTHORIZED_SELECTOR);
            }

            (
                action.liquidatedShares,
                action.debtRepaid,
                action.badDebt
            ) = _canLiquidate(
                debtAmounts[i],
                cachedAccount,
                tData,
                aData,
                action.liquidateExact
            );

            // We optimistically update values even if they are setting from
            // 0 -> 0 to act as an invariant check for the sum of all debt
            // values in `debtAmounts` equal to `debtRepaid`.
            result.debtRepaid += action.debtRepaid;
            result.liquidatedShares[i] = action.liquidatedShares;

            if (action.badDebt > 0) {
                result.badDebtRealized += action.badDebt;
                // Add the bad debt to debt to remove from the liquidated
                // account.
                action.debtRepaid += action.badDebt;
            }

            // If its an exact liquidation this will be a redundant setter
            // but anticipation is majority of liquidators will use
            // non-exact so checking for liquidateExact each time is a
            // waste.
            debtAmounts[i] = action.debtRepaid;

            // Update prior account to current account.
            priorAccount = cachedAccount;
        }

        // If theres no debt to repay then there were no liquidations.
        if (result.debtRepaid == 0) {
            revert MarketManager__NoLiquidationAvailable();
        }

        return (result, debtAmounts);
    }

function canSeize(
        address collateralToken,
        address debtToken
    ) external view {
        _checkIsListedToken(collateralToken);
        _checkIsListedToken(debtToken);

        if (
            ICToken(collateralToken).marketManager() !=
            ICToken(debtToken).marketManager()
        ) {
            revert MarketManager__MarketManagerMismatch();
        }
    }

function _processPositionManagerRedemption(
        uint256 assets,
        uint256 shares,
        address owner,
        uint256 balancePrior,
        IPositionManager.DeleverageAction memory action
    ) internal virtual {
        // Callback to Position Manager to execute remaining deleverage logic.
        IPositionManager(msg.sender).onRedeem(
            address(this),
            assets,
            owner,
            action
        );

        if (balancePrior != balanceOf(owner) + shares) {
            revert BaseCToken__InvariantError();
        }

        // Fails if redemption not allowed.
        uint256 collateralRedeemed = marketManager.canRedeemWithCollateralRemoval(
            address(this),
            shares,
            owner,
            balancePrior,
            collateralPosted[owner],
            false
        );

        if (collateralRedeemed > 0) {
            _removeCollateral(collateralRedeemed, owner);
        }
    }

function claim(bytes memory params_) external override onlyOwner returns (uint256 _claimed) {
        if (!isOpen()) revert PositionIsNotOpen();

        (SwapParams[] memory _swapParams, bytes memory _extraParams) = abi.decode(params_, (SwapParams[], bytes));
        _claimed = _claimAllAndAllocate(_swapParams, _extraParams);

        if (_claimed > 0) {
            uint256 _allocated = _totalAllocated();
            // Note: Using no delta value to not mint shares, therefore considering the claimed amount as profit
            _calculateFeeAndUpdateShares(_allocated, _allocated);
        }

        emit RewardsClaimed(asset(), _claimed);
    }

function collectPendingFees(bytes memory withdrawParams_) public onlyIfCanCollectFees {
        uint256 _pendingFees = getUpdatedPendingFees();

        if (_pendingFees == 0) return;

        IERC20 _asset = asset();
        uint256 _balance = _balanceOf(_asset);
        uint256 _collected = _pendingFees;

        if (_balance < _pendingFees) {
            uint256 _withdrawAmount = Math.min(_pendingFees - _balance, totalAllocated());
            _collected = Math.min(_balance + _withdrawAsset(_withdrawAmount, withdrawParams_), _pendingFees);
        }

        _updateSnapshot({newPendingFees_: _pendingFees - _collected, newTotalAllocated_: totalAllocated()});

        _asset.safeTransfer(positionRegistry().feeCollector(), _collected);

        emit FeesCollected(msg.sender, _asset, _collected);
    }

function updateSnapshot() external {
        if (!isOpen()) revert PositionIsNotOpen();
        PositionStorage storage $ = _getPositionStorage();
        if (block.timestamp < $._latestTimestamp + UPDATE_SNAPSHOT_COOL_DOWN) revert TooEarlyToUpdateSnapshot();

        uint256 _pendingFees = getUpdatedPendingFees();
        uint256 _allocated = _totalAllocated();

        _updateSnapshot(_pendingFees, _allocated);

        emit SnapshotUpdated(msg.sender, block.timestamp, _pendingFees, _allocated);
    }

function _claimAllAndAllocate(
        SwapParams[] memory swapParams_,
        bytes memory extraParams_
    ) internal virtual returns (uint256 _claimed) {}

function _withdrawAsset(uint256 amount_) internal virtual override returns (uint256 _withdrawn) {
        return morpho.delegateWithdraw(marketId(), amount_);
    }

function _withdrawAsset(
        uint256 amount_,
        bytes memory /*extraParams_*/
    ) internal virtual returns (uint256 _withdrawn) {
        return _withdrawAsset(amount_);
    }

function deposit(uint256 assets, address receiver) public virtual returns (uint256) {
        uint256 maxAssets = maxDeposit(receiver);
        if (assets > maxAssets) {
            revert ERC4626ExceededMaxDeposit(receiver, assets, maxAssets);
        }

        uint256 shares = previewDeposit(assets);
        _deposit(_msgSender(), receiver, assets, shares);

        return shares;
    }

function mint(uint256 shares, address receiver) public virtual returns (uint256) {
        uint256 maxShares = maxMint(receiver);
        if (shares > maxShares) {
            revert ERC4626ExceededMaxMint(receiver, shares, maxShares);
        }

        uint256 assets = previewMint(shares);
        _deposit(_msgSender(), receiver, assets, shares);

        return assets;
    }

function processHeldFeesOf(uint256 projectId, address token, uint256 count) external override {
        // Keep a reference to the terminal that'll receive the fees.
        IJBTerminal feeTerminal = _primaryTerminalOf({projectId: JBConstants.FEE_BENEFICIARY_PROJECT_ID, token: token});

        // Process each fee. Re-read the index and array length from storage each iteration to account for reentrant
        // calls that may have already advanced the index or cleaned up the array.
        for (uint256 i; i < count;) {
            // Read the current index from storage (not a cached value) to prevent reentrancy from
            // causing double-processing.
            uint256 currentIndex = _nextHeldFeeIndexOf[projectId][token];

            // If all fees have been processed, break to cleanup.
            if (currentIndex >= _heldFeesOf[projectId][token].length) break;

            // Keep a reference to the held fee being iterated on.
            JBFee memory heldFee = _heldFeesOf[projectId][token][currentIndex];

            // Can't process fees that aren't yet unlocked. Fees unlock sequentially in the array, so nothing left to do
            // if the current fee isn't yet unlocked.
            // forge-lint: disable-next-line(block-timestamp)
            if (heldFee.unlockTimestamp > block.timestamp) break;

            // Delete the entry and advance the index *before* the external call. This is intentional:
            // 1. It prevents reentrancy from reprocessing the same fee.
            // 2. If `_processFee` fails (try-catch), the fee amount is returned to the project's balance via
            //    `_recordAddedBalanceFor` — the fee is forgiven rather than retried. This is a deliberate design
            // choice: projects should not have funds permanently stuck because the fee route is misconfigured or
            // reverting.
            //    A `FeeReverted` event is emitted so the forgiveness is observable off-chain.
            delete _heldFeesOf[projectId][token][currentIndex];
            // `currentIndex` was proven to be within the held-fee array.
            unchecked {
                _nextHeldFeeIndexOf[projectId][token] = currentIndex + 1;
            }

            // Process the standard fee on the original gross amount recorded when the held fee was created.
            _processFee({
                projectId: projectId,
                token: token,
                amount: _feeAmountFrom(heldFee.amount),
                beneficiary: heldFee.beneficiary,
                feeTerminal: feeTerminal,
                wasHeld: true
            });

            unchecked {
                ++i;
            }
        }

        // If all held fees have been processed, reset the array and index entirely to bound storage growth.
        if (
            _nextHeldFeeIndexOf[projectId][token] >= _heldFeesOf[projectId][token].length
                && _heldFeesOf[projectId][token].length > 0
        ) {
            delete _heldFeesOf[projectId][token];
            delete _nextHeldFeeIndexOf[projectId][token];
        }
    }

function sendPayoutsOf(
        uint256 projectId,
        address token,
        uint256 amount,
        uint256 currency,
        uint256 minTokensPaidOut
    )
        external
        override
        returns (uint256 amountPaidOut)
    {
        amountPaidOut = _sendPayoutsOf({projectId: projectId, token: token, amount: amount, currency: currency});

        // The amount being paid out must be at least as much as was expected.
        _checkMin({value: amountPaidOut, min: minTokensPaidOut});
    }

function _sendPayoutsOf(
        uint256 projectId,
        address token,
        uint256 amount,
        uint256 currency
    )
        internal
        returns (uint256 amountPaidOut)
    {
        // Cache the message sender.
        address sender = _msgSender();

        // Keep a reference to the ruleset.
        JBRuleset memory ruleset;

        // Record the payout.
        (ruleset, amountPaidOut) =
            STORE.recordPayoutFor({projectId: projectId, token: token, amount: amount, currency: currency});

        // If nothing to pay out (e.g. payout limit already used or not configured), return early.
        if (amountPaidOut == 0) return amountPaidOut;

        // Get a reference to the project's owner.
        // The owner will receive tokens minted by paying the platform fee and receive any leftover funds not sent to
        // payout splits.
        address payable projectOwner = payable(_ownerOf(projectId));

        // If the ruleset requires privileged payout distribution, ensure the caller has the permission.
        if (ruleset.ownerMustSendPayouts()) {
            // Enforce permissions.
            _requirePermissionFrom({
                account: projectOwner, projectId: projectId, permissionId: JBPermissionIds.SEND_PAYOUTS
            });
        }

        // Send payouts to the splits and get a reference to the amount left over after the splits have been paid.
        // Also get a reference to the amount which was paid out to splits that is eligible for fees.
        (uint256 leftoverPayoutAmount, uint256 amountEligibleForFees) = JBPayoutSplitGroupLib.sendPayoutsToSplitGroupOf({
            splits: SPLITS,
            store: STORE,
            projectId: projectId,
            token: token,
            rulesetId: ruleset.id,
            amount: amountPaidOut,
            caller: sender
        });

        // Send any leftover funds to the project owner and update the fee tracking accordingly.
        if (leftoverPayoutAmount != 0) {
            // Keep a reference to the fee for the leftover payout amount.
            uint256 fee =
                _isFeeless({addr: projectOwner, projectId: projectId}) ? 0 : _feeAmountFrom(leftoverPayoutAmount);

            uint256 netLeftoverPayoutAmount;
            unchecked {
                netLeftoverPayoutAmount = leftoverPayoutAmount - fee;
            }

            // Failed owner transfer consumes the payout limit by design. Same pattern as split payouts:
            // the try-catch prevents revert, failed amount is returned to project balance, and the owner can retry
            // via addToBalanceOf or in the next cycle.
            try this.executeTransferTo({addr: projectOwner, token: token, amount: netLeftoverPayoutAmount}) {
                if (fee > 0) {
                    amountEligibleForFees += leftoverPayoutAmount;
                    leftoverPayoutAmount = netLeftoverPayoutAmount;
                }
            } catch (bytes memory reason) {
                emit PayoutTransferReverted({
                    projectId: projectId,
                    addr: projectOwner,
                    token: token,
                    amount: netLeftoverPayoutAmount,
                    fee: fee,
                    reason: reason,
                    caller: sender
                });

                // Add balance back to the project.
                _recordAddedBalanceFor({projectId: projectId, token: token, amount: leftoverPayoutAmount});
            }
        }

        // Cap fee-free surplus at remaining balance. Non-fee-free funds leave first.
        // Placed after all payouts settle so the cap reflects post-payout state.
        _capFeeFreeSurplus({projectId: projectId, token: token});

        // Take the fee.
        uint256 feeTaken = _takeFeeFrom({
            projectId: projectId,
            token: token,
            amount: amountEligibleForFees,
            beneficiary: projectOwner,
            shouldHoldFees: ruleset.holdFees()
        });

        emit SendPayouts({
            rulesetId: ruleset.id,
            rulesetCycleNumber: ruleset.cycleNumber,
            projectId: projectId,
            projectOwner: projectOwner,
            amount: amount,
            amountPaidOut: amountPaidOut,
            fee: feeTaken,
            netLeftoverPayoutAmount: leftoverPayoutAmount,
            caller: sender
        });
    }

function sendPayoutsToSplitGroupOf(
        IJBSplits splits,
        IJBTerminalStore store,
        uint256 projectId,
        address token,
        uint256 rulesetId,
        uint256 amount,
        address caller
    )
        external
        returns (uint256 leftoverAmount, uint256 amountEligibleForFees)
    {
        // The total percentage available to split.
        uint256 leftoverPercentage = JBConstants.SPLITS_TOTAL_PERCENT;

        // Get a reference to the project's payout splits.
        JBSplit[] memory payoutSplits =
            splits.splitsOf({projectId: projectId, rulesetId: rulesetId, groupId: uint256(uint160(token))});

        leftoverAmount = amount;

        // Transfer between all splits.
        for (uint256 i; i < payoutSplits.length;) {
            // Get a reference to the split being iterated on.
            JBSplit memory split = payoutSplits[i];

            // The amount to send to the split.
            uint256 payoutAmount = mulDiv({x: leftoverAmount, y: split.percent, denominator: leftoverPercentage});

            // Send the payout (inlined to keep stack pressure manageable with the tuple return).
            // Returns (netPayoutAmount sent, feeEligible gross-equivalent). For non-hook splits and fully-consumed
            // hook splits, `feeEligible` equals `payoutAmount` (non-feeless) or 0 (feeless). For a partial split-hook
            // pull, `feeEligible` scales with consumed. Failed payouts consume the payout limit by design — the
            // try/catch keeps a single bad split from DoS-ing the rest and restores balance.
            uint256 netPayoutAmount;
            try IJBPayoutSplitGroupExecutor(address(this))
                .executePayout({
                split: split, projectId: projectId, token: token, amount: payoutAmount, originalMessageSender: caller
            }) returns (
                uint256 sentAmount, uint256 feeEligible
            ) {
                netPayoutAmount = sentAmount;
                // The standard fee is `STANDARD_FEE / MAX_FEE`, currently 25 / 1000 = 1 / 40. The `40` below is
                // that reduced denominator, not an independent fee parameter. Round each split's fee basis down to
                // it so aggregation cannot charge more than per-split floors.
                amountEligibleForFees += feeEligible - (feeEligible % 40);
            } catch (bytes memory failureReason) {
                emit PayoutReverted({
                    projectId: projectId, split: split, amount: payoutAmount, reason: failureReason, caller: caller
                });
                store.recordAddedBalanceFor({projectId: projectId, token: token, amount: payoutAmount});
            }

            if (payoutAmount != 0) {
                // Subtract from the amount to be sent to the beneficiary.
                unchecked {
                    leftoverAmount -= payoutAmount;
                }
            }

            unchecked {
                // Decrement the leftover percentage.
                leftoverPercentage -= split.percent;
            }

            emit SendPayoutToSplit({
                projectId: projectId,
                rulesetId: rulesetId,
                group: uint256(uint160(token)),
                split: split,
                amount: payoutAmount,
                netAmount: netPayoutAmount,
                caller: caller
            });
            unchecked {
                ++i;
            }
        }
    }

function poolCollateral(
        address _accountAddress,
        address _tokenAddress,
        uint256 _amount
    ) external onlyEnabledCollateralTokens(_tokenAddress) {
        _requireCollateralizableAndDecreaseApprovedAmount(msg.sender, _accountAddress, _tokenAddress, _amount);

        _transferCollateral(_tokenAddress, _accountAddress, _amount, msg.sender);
    }

function transferCollateral(address _tokenAddress, uint256 _amount, address _destinationAddress) external {
        _transferCollateral(_tokenAddress, msg.sender, _amount, _destinationAddress);
    }

function depositAndApprove(
        address[] calldata _tokenAddresses,
        uint256[] calldata _amounts,
        address _collateralizableContractAddressToApprove
    ) external {
        if (!collateralizableContracts[_collateralizableContractAddressToApprove])
            revert ContractNotApprovedByProtocol(_collateralizableContractAddressToApprove);

        depositToAccount(msg.sender, _tokenAddresses, _amounts);
        for (uint256 i = 0; i < _amounts.length; i++) {
            _authorizedModifyCollateralizableTokenAllowance(
                msg.sender,
                _collateralizableContractAddressToApprove,
                _tokenAddresses[i],
                Pricing.safeCastToInt256(_amounts[i])
            );
        }
    }

function _requireCollateralizableAndDecreaseApprovedAmount(
        address _collateralizableAddress,
        address _accountAddress,
        address _tokenAddress,
        uint256 _amount
    ) internal {
        if (_collateralizableAddress == _accountAddress) {
            return;
        }
        if (!collateralizableContracts[_collateralizableAddress])
            revert ContractNotApprovedByProtocol(_collateralizableAddress);

        uint256 approvedAmount = accountCollateralizableTokenAllowances[_accountAddress][_collateralizableAddress][
            _tokenAddress
        ];
        if (approvedAmount < _amount)
            revert InsufficientAllowance(
                _collateralizableAddress,
                _accountAddress,
                _tokenAddress,
                _amount,
                approvedAmount
            );

        accountCollateralizableTokenAllowances[_accountAddress][_collateralizableAddress][_tokenAddress] =
            approvedAmount -
            _amount;
    }

function _transferCollateral(
        address _tokenAddress,
        address _fromAddress,
        uint256 _amount,
        address _destinationAddress
    ) private {
        if (_amount == 0 || _fromAddress == _destinationAddress) {
            // NB: 0 amounts should not revert, as transferCollateral may be used by pool contracts to do the reverse of
            // poolCollateral(...). If those contracts do not check for 0, reverting here may cause them to deadlock.
            return;
        }

        CollateralBalance storage fromStorage = accountBalances[_fromAddress][_tokenAddress];
        uint256 fromAvailable = fromStorage.available;
        if (_amount > fromAvailable) {
            revert InsufficientCollateral(_amount, fromAvailable);
        }

        accountBalances[_destinationAddress][_tokenAddress].available += _amount;
        fromStorage.available = fromAvailable - _amount;

        emit CollateralTransferred(_fromAddress, _tokenAddress, _destinationAddress, _amount);
    }

function mint(
        uint256 shares,
        address receiver
    )
        public
        virtual
        override
        nonReentrant
        noNavPerShareDecrease(TotalAssetPurpose.Deposit)
        ensureNoNavOps
        returns (uint256 assets)
    {
        AutopoolState storage $ = AutopoolStorage.load();
        // Handles the vault being paused, returns 0
        if (shares > maxMint(receiver)) {
            revert ERC4626MintExceedsMax(shares, maxMint(receiver));
        }

        uint256 ta = $.totalAssetsTimeChecked(TotalAssetPurpose.Deposit);
        assets = convertToAssets(shares, ta, totalSupply(), Math.Rounding.Up);

        $.transferAndMint(_baseAsset, assets, shares, receiver);

        onDeposit(assets, shares, receiver);
    }

function mint(TokenData storage data, address account, uint256 value) external {
        if (account == address(0)) {
            revert ERC20InvalidReceiver(address(0));
        }
        _update(data, address(0), account, value);
    }

function withdraw(
        uint256 assets,
        address receiver,
        address owner
    )
        external
        virtual
        override
        nonReentrant
        whenNotPaused
        noNavPerShareDecrease(TotalAssetPurpose.Withdraw)
        ensureNoNavOps
        returns (uint256 shares)
    {
        Errors.verifyNotZero(assets, "assets");
        AutopoolState storage $ = AutopoolStorage.load();

        //slither-disable-next-line unused-return
        (uint256 actualAssets, uint256 actualShares,) =
            AutopoolDebt.withdraw($, assets, $.totalAssetsTimeChecked(TotalAssetPurpose.Withdraw));

        shares = actualShares;

        _completeWithdrawal($, actualAssets, shares, owner, receiver);
    }

function withdraw(
        AutopoolState storage $,
        uint256 assets,
        uint256 applicableTotalAssets
    ) public returns (uint256 actualAssets, uint256 actualShares, uint256 debtBurned) {
        WithdrawInfo memory info = _initiateWithdrawInfo(assets, $.assetBreakdown);

        // Pull the market if there aren't enough funds in idle to cover the entire amount

        // This flow is not bounded by a set number of shares. The user has requested X assets
        // and a variable number of shares to burn so we don't have easy break out points like we do
        // during redeem (like using debt burned). When we get slippage here and don't meet the requested assets
        // we need to keep going if we can. This is tricky if we consider that (most of) our destinations are
        // LP positions and we'll be swapping assets, so we can expect some slippage. Even
        // if our minDebtValue numbers are up to date and perfectly accurate slippage could ensure we
        // are always receiving less than we expect/calculate and we never hit the requested assets
        // even though the owner would have shares to cover it. Under normal/expected conditions, our
        // minDebtValue is lower than actual and we expect overall value to be going up, so we burn a tad
        // more than we should and receive a tad more than we expect. This should cover us. However,
        // in other conditions we have to be sure we aren't endlessly trying to approach 0 so we are tracking
        // the slippage we received on the last pull, repricing, and applying an increasing multiplier until we either
        // pull enough to cover or pull them all and/or move to the next destination.

        uint256 dvSharesToBurn;
        while (info.assetsToPull > 0) {
            IDestinationVault destVault = IDestinationVault($.withdrawalQueue.peekHead());

            // We've run out of destinations
            if (address(destVault) == address(0)) {
                break;
            }

            uint256 dvShares = destVault.balanceOf(address(this));
            {
                uint256 dvSharesValue;
                if (info.destinationRound == 0) {
                    // First time pulling

                    // We use the min debt value here because its a withdrawal and we're trying to cover an amount
                    // of assets. Undervaluing the shares may mean we pull more but given that we expect slippage
                    // that is desirable.
                    dvSharesValue = $.destinationInfo[address(destVault)].cachedMinDebtValue * dvShares
                        / $.destinationInfo[address(destVault)].ownedShares;
                } else {
                    // When we've pulled from this destination before, i.e. destinationRound > 0, then we
                    // know a more accurate exchange rate and its worse than we were expecting.
                    // We even will pad it a bit as we want to account for any additional slippage we
                    // may receive by say being farther down an AMM curve.

                    // dvSharesToBurn is the last value we used when pulling from this destination
                    // info.expectedAssets is how much we expected to get on that last pull
                    // info.expectedAssets - info.lastRoundSlippage is how much we actually received

                    uint256 paddedSlippage = info.lastRoundSlippage * (info.destinationRound + 10_000) / 10_000;

                    if (paddedSlippage < info.expectedAssets) {
                        dvSharesValue = (info.expectedAssets - paddedSlippage) * dvShares / dvSharesToBurn;
                    } else {
                        // This will just mean we pull all shares
                        dvSharesValue = 0;
                    }
                }

                if (dvSharesValue > info.assetsToPull) {
                    dvSharesToBurn = (dvShares * info.assetsToPull) / dvSharesValue;

                    // On withdraw, we are trying to meet a specific number of assets without a limit
                    // on the debt we can burn. Burning 0 due to the valuations here would be an automatic failure
                    // as we still have assets to satisfy and debt to burn. We at least have to burn 1 even if it
                    // results in a larger over pull
                    if (dvSharesToBurn == 0) {
                        dvSharesToBurn = 1;
                    }

                    // Only need to set it here because the only time we'll use it is if
                    // we don't exhaust all shares and have to try the destination again
                    info.expectedAssets = info.assetsToPull;
                } else {
                    dvSharesToBurn = dvShares;
                }
            }

            uint256 pulledAssets;
            uint256 debtValueBurned;
            // Get the base asset back from the Destination. Also performs a check that we aren't receiving
            // poor execution on our swaps based on safe prices
            (info, pulledAssets, debtValueBurned) = _withdrawAssets(info, $.destinationInfo, destVault, dvSharesToBurn);

            info.assetsPulled += pulledAssets;

            if (info.remainingRecoup > 0) {
                // If the destination is so severely undervalued that it can't cover its own recoup then we have no
                // recourse but to burn the entire destination and the user would to have to cover the full overage
                // from the next destinations can get nothing from this one. Should not be allowed.
                revert PositivePriceRecoupNotCovered(info.remainingRecoup);
            }

            // If we've exhausted all shares we can remove the withdrawal from the queue
            // We need to leave it in the debt report queue though so that our destination specific
            // debt tracking values can be updated
            if (dvShares == dvSharesToBurn) {
                $.withdrawalQueue.popAddress(address(destVault));
                info.destinationRound = 0;
                info.lastRoundSlippage = 0;
            } else {
                // If we didn't burn all the shares and we received enough to cover our
                // expected that means we'll break out below as we've hit our target
                unchecked {
                    if (pulledAssets < info.expectedAssets) {
                        info.lastRoundSlippage = info.expectedAssets - pulledAssets;
                        if (info.destinationRound == 0) {
                            info.destinationRound = 100;
                        } else {
                            info.destinationRound *= 2;
                        }
                    }
                }
            }

            // It's possible we'll get back more assets than we anticipate from a swap
            // so if we do, throw it in idle and stop processing. You don't get more than we've calculated
            if (info.assetsPulled >= info.totalAssetsToPull) {
                info.idleIncrease += info.assetsPulled - info.totalAssetsToPull;
                info.assetsPulled = info.totalAssetsToPull;
                info.assetsToPull = 0;
                break;
            }

            info.assetsToPull -= pulledAssets;
        }

        // We didn't get enough assets from the debt pull
        // See if we can get the rest from idle
        if (info.assetsPulled < assets && info.currentIdle > 0) {
            uint256 remaining = assets - info.assetsPulled;
            if (remaining <= info.currentIdle) {
                info.assetsFromIdle = remaining;
            }
            // We don't worry about the else case because if currentIdle can't
            // cover remaining then we'll fail the `actualAssets < assets`
            // check below and revert
        }

        debtBurned = info.assetsFromIdle + info.debtMinDecrease;
        actualAssets = info.assetsFromIdle + info.assetsPulled;

        if (actualAssets < assets) {
            revert TooFewAssets(assets, actualAssets);
        }

        actualShares = IAutopool(address(this)).convertToShares(
            Math.max(actualAssets, debtBurned),
            applicableTotalAssets,
            IAutopool(address(this)).totalSupply(),
            Math.Rounding.Up
        );

        // Subtract what's taken out of idle from totalIdle
        // We may also have some increase to account for it we over pulled
        // or received better execution than we were anticipating
        // slither-disable-next-line events-maths
        $.assetBreakdown.totalIdle = info.currentIdle + info.idleIncrease - info.assetsFromIdle;

        // Save off our various debt numbers
        if (info.debtDecrease > $.assetBreakdown.totalDebt) {
            $.assetBreakdown.totalDebt = 0;
        } else {
            $.assetBreakdown.totalDebt -= info.debtDecrease;
        }

        if (info.debtMinDecrease > info.totalMinDebt) {
            $.assetBreakdown.totalDebtMin = 0;
        } else {
            $.assetBreakdown.totalDebtMin -= info.debtMinDecrease;
        }

        if (info.debtMaxDecrease > $.assetBreakdown.totalDebtMax) {
            $.assetBreakdown.totalDebtMax = 0;
        } else {
            $.assetBreakdown.totalDebtMax -= info.debtMaxDecrease;
        }
    }

function batchLiquidate(uint256[] calldata accountIds)
        external
        returns (uint256 totalAmountLiquidated, uint256 totalFeesInYield, uint256 totalFeesInUnderlying)
    {
        if (accountIds.length == 0) {
            revert MissingInputData();
        }

        bool anyProgress = false;
        for (uint256 i = 0; i < accountIds.length; i++) {
            uint256 accountId = accountIds[i];
            if (accountId == 0 || !_tokenExists(alchemistPositionNFT, accountId)) {
                continue;
            }
            uint256 debtBefore = _accounts[accountId].debt;
            (uint256 underlyingAmount, uint256 feeInYield, uint256 feeInUnderlying) = _liquidate(accountId);
            totalAmountLiquidated += underlyingAmount;
            totalFeesInYield += feeInYield;
            totalFeesInUnderlying += feeInUnderlying;
            if (
                underlyingAmount > 0 || feeInYield > 0 || feeInUnderlying > 0 || _accounts[accountId].debt < debtBefore
            ) {
                anyProgress = true;
            }
        }

        if (anyProgress) {
            return (totalAmountLiquidated, totalFeesInYield, totalFeesInUnderlying);
        } else {
            // None of the requested accounts made progress.
            revert LiquidationError();
        }
    }

function poke(uint256 tokenId) external {
        _checkForValidAccountId(tokenId);
        _poke(tokenId);
    }

function mintFrom(uint256 tokenId, uint256 amount, address recipient) external {
        _checkArgument(amount > 0);
        _checkForValidAccountId(tokenId);
        _checkArgument(recipient != address(0));
        _checkState(!loansPaused);
        // Preemptively try and decrease the minting allowance. This will save gas when the allowance is not sufficient.
        _decreaseMintAllowance(tokenId, msg.sender, amount);

        // Query transmuter and earmark global debt
        _earmark();
        _checkState(!_isProtocolInBadDebt());
        // Sync current user debt before more is taken
        _sync(tokenId);

        // Mint tokens from the tokenId's account to the recipient.
        _mint(tokenId, amount, recipient);
    }

function _decreaseMintAllowance(uint256 ownerTokenId, address spender, uint256 amount) internal {
        Account storage account = _accounts[ownerTokenId];
        account.mintAllowances[account.allowancesVersion][spender] -= amount;
    }

function _mint(uint256 tokenId, uint256 amount, address recipient) internal {
        if (block.number == _accounts[tokenId].lastRepayBlock) revert CannotMintOnRepayBlock();
        _addDebt(tokenId, amount);

        totalSyntheticsIssued += amount;

        // Validate the tokenId's account to assure that the collateralization invariant is still held.
        _validate(tokenId);

        _accounts[tokenId].lastMintBlock = block.number;

        // Mint the debt tokens to the recipient.
        TokenUtils.safeMint(debtToken, recipient, amount);

        emit Mint(tokenId, amount, recipient);
    }

function _liquidate(uint256 accountId) internal returns (uint256 amountLiquidated, uint256 feeInYield, uint256 feeInUnderlying) {
        // Query transmuter and earmark global debt
        _earmark();
        // Sync current user debt before deciding how much needs to be liquidated
        _sync(accountId);

        Account storage account = _accounts[accountId];

        // If one share is worth zero underlying, liquidation math is undefined and should noop.
        if (IVaultV2(myt).convertToAssets(1e18) == 0) {
            return (0, 0, 0);
        }

        if (_isAccountHealthy(accountId, false)) {
            return (0, 0, 0);
        }

        // First try to clear earmarked debt from the account's own collateral.
        uint256 repaidAmountInYield = 0;
        if (account.earmarked > 0) {
            repaidAmountInYield = _forceRepay(accountId, account.earmarked, false);
            feeInYield = _calculateRepaymentFee(repaidAmountInYield);
            // Final safety check after all deductions
            if (account.collateralBalance == 0 && account.debt > 0) {
                uint256 debtToClear = _clearableDebt(account.debt);
                if (debtToClear > 0) {
                    _subDebt(accountId, debtToClear);
                }
            }
        }

        // Recalculate ratio after any repayment to determine if further liquidation is needed
        if (_isAccountHealthy(accountId, false)) {
            if (feeInYield > 0) {
                uint256 targetFeeInYield = feeInYield;
                uint256 maxSafeFeeInYield = _maxRepaymentFeeInYield(accountId);
                // Use a single fee source: either the account can safely cover the full fee in MYT,
                // or the entire fee is outsourced to the fee vault.
                if (maxSafeFeeInYield < targetFeeInYield) {
                    feeInYield = 0;
                    feeInUnderlying = convertYieldTokensToUnderlying(targetFeeInYield);
                }
            }

            if (feeInYield > 0) {
                feeInYield = _subCollateralBalance(feeInYield, accountId); // clamps to available balance
                TokenUtils.safeTransfer(myt, msg.sender, feeInYield);
            } else if (feeInUnderlying > 0) {
                feeInUnderlying = _payWithFeeVault(feeInUnderlying);
            }
            emit RepaymentFee(accountId, msg.sender, feeInYield, feeInUnderlying);
            return (repaidAmountInYield, feeInYield, feeInUnderlying);
        } else {
            // Do actual liquidation
            return _doLiquidation(accountId);
        }

    }

function _doLiquidation(uint256 accountId)
        internal
        returns (uint256 amountLiquidated, uint256 feeInYield, uint256 feeInUnderlying)
    {
        Account storage account = _accounts[accountId];
        uint256 debt = account.debt;
        uint256 collateralInUnderlying = totalValue(accountId);
        (uint256 liquidationAmount, uint256 debtToBurn, uint256 baseFee, uint256 outsourcedFee) = calculateLiquidation(
            collateralInUnderlying,
            debt,
            liquidationTargetCollateralization,
            normalizeUnderlyingTokensToDebt(_getTotalUnderlyingValue()) * FIXED_POINT_SCALAR / totalDebt,
            globalMinimumCollateralization,
            liquidatorFee
        );

        if (liquidationAmount == 0) {
            // Debt-only closeout path: account can be insolvent with no remaining collateral to seize.
            if (debtToBurn > 0) {
                uint256 burnableDebt = _capDebtCredit(debtToBurn, account.debt);
                if (burnableDebt > 0) {
                    _subDebt(accountId, burnableDebt);
                }
            }

            uint256 feeRequestInUnderlying = normalizeDebtTokensToUnderlying(outsourcedFee);
            if (feeRequestInUnderlying > 0) {
                feeInUnderlying = _payWithFeeVault(feeRequestInUnderlying);
            }

            if (account.debt < debt || feeInUnderlying > 0) {
                emit Liquidated(accountId, msg.sender, 0, 0, feeInUnderlying);
                return (0, 0, feeInUnderlying);
            }

            return (0, 0, 0);
        }

        uint256 requestedLiquidationInYield = convertDebtTokensToYield(liquidationAmount);
        amountLiquidated = _subCollateralBalance(requestedLiquidationInYield, accountId);
        if (amountLiquidated == 0) return (0, 0, 0);

        // Fee and debt burn are derived from idealized liquidation math, so clamp them to what was
        // actually realized after collateral capping to avoid underflow and over-burning debt.
        uint256 requestedFeeInYield = convertDebtTokensToYield(baseFee);
        feeInYield = requestedFeeInYield > amountLiquidated ? amountLiquidated : requestedFeeInYield;

        uint256 netToTransmuter = amountLiquidated - feeInYield;
        uint256 maxDebtByRealized = convertYieldTokensToDebt(netToTransmuter);
        uint256 maxDebtByStorage = account.debt < totalDebt ? account.debt : totalDebt;

        if (debtToBurn > maxDebtByRealized) debtToBurn = maxDebtByRealized;
        if (debtToBurn > maxDebtByStorage) debtToBurn = maxDebtByStorage;

        // Apply the realized debt reduction.
        if (debtToBurn > 0) {
            _subDebt(accountId, debtToBurn);
        }

        // If liquidation still leaves the account unhealthy, force-close the residual:
        // sweep all remaining collateral and clear any debt that cannot be backed anymore.
        if (account.debt > 0 && !_isAccountHealthy(accountId, false)) {
            uint256 remainingShares = account.collateralBalance;
            if (remainingShares > 0) {
                uint256 removedShares = _subCollateralBalance(remainingShares, accountId);
                netToTransmuter += removedShares;

                uint256 extraDebtBurn = _capDebtCredit(convertYieldTokensToDebt(removedShares), account.debt);
                if (extraDebtBurn > 0) {
                    _subDebt(accountId, extraDebtBurn);
                }
            }

            if (account.collateralBalance == 0 && account.debt > 0) {
                uint256 debtToClear = _clearableDebt(account.debt);
                if (debtToClear > 0) {
                    _subDebt(accountId, debtToClear);
                }
            }
        }

        // Route seized collateral net of liquidator fee to the transmuter.
        if (netToTransmuter > 0) {
            _syncEarmarkedTransmuterTransfer(netToTransmuter, 0);
            TokenUtils.safeTransfer(myt, transmuter, netToTransmuter);
        }

        // Pay the liquidator from MYT if available, otherwise fall back to the fee vault.
        if (feeInYield > 0) {
            TokenUtils.safeTransfer(myt, msg.sender, feeInYield);
        } else if (normalizeDebtTokensToUnderlying(outsourcedFee) > 0) {
            feeInUnderlying = _payWithFeeVault(normalizeDebtTokensToUnderlying(outsourcedFee));
        }
        emit Liquidated(accountId, msg.sender, amountLiquidated, feeInYield, feeInUnderlying);
        return (amountLiquidated, feeInYield, feeInUnderlying);
    }

function _poke(uint256 tokenId) internal {
        _earmark();
        _sync(tokenId);
    }

function liquidate(uint256 accountId) external override returns (uint256 yieldAmount, uint256 feeInYield, uint256 feeInUnderlying) {
        _checkForValidAccountId(accountId);
        uint256 debtBefore = _accounts[accountId].debt;
        (yieldAmount, feeInYield, feeInUnderlying) = _liquidate(accountId);
        if (yieldAmount > 0 || feeInYield > 0 || feeInUnderlying > 0 || _accounts[accountId].debt < debtBefore) {
            return (yieldAmount, feeInYield, feeInUnderlying);
        } else {
            // No collateral or fee movement occurred and debt did not decrease.
            revert LiquidationError();
        }
    }

function claimLendingRewards(
    ILendingStorageManager.LendingInfo calldata _lendingInfo,
    ILendingStorageManager.PoolLendingStorage calldata _poolLendingStorage,
    address _recipient
  ) external override {
    ISynthereumFinder finderContract = finder;
    ILendingManager lendingManager = SynthereumMultiLpLiquidityPoolLib
      ._getLendingManager(finderContract);
    require(
      msg.sender == address(lendingManager),
      'Sender must be the lending manager'
    );

    require(
      _poolLendingStorage.collateralToken ==
        address(storageParams.collateralAsset),
      'Wrong collateral passed'
    );
    address interestToken = SynthereumMultiLpLiquidityPoolLib
      ._getLendingStorageManager(finderContract)
      .getInterestBearingToken(address(this));
    require(
      _poolLendingStorage.interestToken == interestToken,
      'Wrong bearing token passed'
    );
    address(_lendingInfo.lendingModule).functionDelegateCall(
      abi.encodeWithSignature(
        CLAIM_REWARDS_SIG,
        _lendingInfo.args,
        _poolLendingStorage.collateralToken,
        _poolLendingStorage.interestToken,
        _recipient
      )
    );
  }

function swap(
        address tokenIn,
        address tokenOut,
        uint256 amount,
        address recipient
    ) external isNotLocked whenNotPaused {
        _swap(tokenIn, tokenOut, amount, recipient);
    }

function _swap(address tokenIn, address tokenOut, uint256 amount, address recipient) internal {
        // Prevent self-swaps (e.g., PYUSDX -> PYUSDX or extension -> same extension)
        if (tokenIn == tokenOut) revert InvalidSwapPath(tokenIn, tokenOut);

        // If the input token is PYUSDX, we swap it for the output token, which must be an approved extension
        // This is checked in _swapIn
        if (tokenIn == pyusdx) return _swapIn(tokenOut, amount, recipient);

        // If the output token is PYUSDX, we swap the input token, which must be an approved extension, for PYUSDX
        // This is checked in _swapOut
        if (tokenOut == pyusdx) return _swapOut(tokenIn, amount, recipient);

        // If both tokens are extensions, we swap one extension for another
        bool isTokenOutApproved = isApprovedExtension(tokenOut);
        if (isApprovedExtension(tokenIn) && isTokenOutApproved)
            return _swapExtensions(tokenIn, tokenOut, amount, recipient);

        // If tokenOut is an extension but tokenIn is an external asset, route through MultiMint
        if (isTokenOutApproved) return _swapInMultiMint(tokenIn, tokenOut, amount, recipient);

        // If none of the above, we revert
        revert InvalidSwapPath(tokenIn, tokenOut);
    }

function _swapInMultiMint(address asset, address extensionOut, uint256 amount, address recipient) internal {
        _revertIfCannotMultiMint(asset, extensionOut);

        uint256 balanceBefore = IERC20(asset).balanceOf(address(this));

        // NOTE: Use safeTransferFrom and forceApprove to handle assets that do not return a boolean value.
        // NOTE: Fee-on-transfer tokens are not supported. The full `amount` must be received by the contract.
        IERC20(asset).safeTransferFrom(msg.sender, address(this), amount);
        IERC20(asset).forceApprove(extensionOut, amount);
        IMultiMint(extensionOut).wrap(asset, recipient, amount);

        // NOTE: Refund any dust the extension left behind to the caller.
        uint256 leftover = IERC20(asset).balanceOf(address(this)) - balanceBefore;

        if (leftover != 0) {
            // NOTE: Clear the residual allowance scoped to this swap.
            IERC20(asset).forceApprove(extensionOut, 0);
            IERC20(asset).safeTransfer(msg.sender, leftover);
        }

        emit SwappedInMultiMint(asset, extensionOut, amount - leftover, recipient);
    }

function _swapExtensions(address extensionIn, address extensionOut, uint256 amount, address recipient) internal {
        uint256 pyusdxBalanceBefore = _pyusdxBalanceOf(address(this));

        IERC20(extensionIn).transferFrom(msg.sender, address(this), amount);
        IExtension(extensionIn).unwrap(amount);

        // NOTE: Ensures that we wrap the equivalent amount of PYUSDX received from unwrapping.
        amount = _pyusdxBalanceOf(address(this)) - pyusdxBalanceBefore;

        IERC20(pyusdx).approve(extensionOut, amount);
        IExtension(extensionOut).wrap(recipient, amount);

        emit Swapped(extensionIn, extensionOut, amount, recipient);
    }

function _revertIfCannotMultiMint(address asset, address extensionOut) internal view {
        try IMultiMint(extensionOut).isAllowedAsset(asset) returns (bool allowed) {
            if (!allowed) revert InvalidSwapPath(asset, extensionOut);
        } catch {
            revert InvalidSwapPath(asset, extensionOut);
        }
    }

function takeFees() external whenNotPaused {
        _takeFees();
    }

function mint(uint256 shares) external returns (uint256) {
        return mint(shares, msg.sender);
    }

function mint(
        uint256 shares,
        address receiver
    ) public override whenNotPaused returns (uint256 assets) {
        // Additional logic for inheriting contracts
        beforeDeposit(assets, shares);

        require(shares != 0, "ZERO_SHARES");

        assets = previewMint(shares); // No need to check for rounding error, previewMint rounds up.

        // Need to transfer before minting or ERC777s could reenter.
        SafeTransferLib.safeTransferFrom(
            asset,
            msg.sender,
            address(this),
            assets
        );

        _mint(receiver, shares);

        emit Deposit(msg.sender, receiver, assets, shares);

        // Additional logic for inheriting contracts
        afterDeposit(assets, shares);
    }

function mint(uint256 shares, address receiver) public virtual returns (uint256 assets) {
        assets = previewMint(shares); // No need to check for rounding error, previewMint rounds up.

        // Need to transfer before minting or ERC777s could reenter.
        asset.safeTransferFrom(msg.sender, address(this), assets);

        _mint(receiver, shares);

        emit Deposit(msg.sender, receiver, assets, shares);

        afterDeposit(assets, shares);
    }

function previewMint(
        uint256 shares
    ) public view override returns (uint256) {
        Limits memory limits_ = limits;
        uint256 assets = convertToAssets(shares);

        if (
            paused ||
            totalAssets() + assets > limits_.depositLimit ||
            shares < limits_.minAmount
        ) return 0;

        return super.previewMint(shares);
    }

function previewMint(
        uint256 shares
    ) public view virtual override returns (uint256) {
        return paused ? 0 : super.previewMint(shares);
    }

function previewMint(uint256 shares) public view virtual returns (uint256) {
        uint256 supply = totalSupply; // Saves an extra SLOAD if totalSupply is non-zero.

        return supply == 0 ? shares : shares.mulDivUp(totalAssets(), supply);
    }

function _takeFees() internal {
        Fees memory fees_ = fees;
        uint256 fee = _accruedFees(fees_);
        uint256 shareValue = convertToAssets(10 ** asset.decimals());

        if (shareValue > fees_.highWaterMark) fees.highWaterMark = shareValue;

        if (fee > 0) _mint(fees_.feeRecipient, convertToShares(fee));

        fees.feesUpdatedAt = uint64(block.timestamp);
    }

function repayBadDebt(uint256 amount) external nonReentrant {
        uint256 _badDebt = badDebt;
        require(amount <= _badDebt, RepayMoreThanBadDebt());
        badDebt = _badDebt - amount;
        _burnUSG(msg.sender, amount);

        emit RepayBadDebt(msg.sender, amount);
    }

function requestEmergencyWithdraw(uint256 amount) external nonReentrant whenNotPaused {
        uint price = exchangePrice();
        uint USDFAmount = amount * price / EXCHANGE_PRICE_DECIMALS;
        USDF.safeTransfer(address(WITHDRAW_VAULT), USDFAmount);
        Withdrawable._doRequestWithdraw(amount, USDFAmount, price, true);
        asUSDF.burn(address(this), amount);
    }

function _doRequestWithdraw(uint amount, uint receiveAmount,  uint exchangePrice, bool emergency) internal {
        Storage storage st = getStorage();
        require(st.withdrawEnabled == true, "withdraw paused");
        require(amount > 0, "invalid amount");
        if (emergency) {
            require(
                st.emergencyWithdrawEnabled || st.emergencyWithdrawWhitelist[msg.sender], 
                "not support emergency withdraw"
            );
        }

        asToken.safeTransferFrom(msg.sender, address(this), amount);

        RequestWithdrawInfo memory requestWithdrawInfo = RequestWithdrawInfo({
            withdrawToken: asToken,
            withdrawAmount: amount,
            receiveAmount: receiveAmount,
            withdrawTime: block.timestamp,
            exchangePrice: exchangePrice,
            claimable: false,
            receipt: msg.sender,
            emergency: emergency
        });
        st.requestWithdrawMaxNo += 1;
        st.requestWithdraws[st.requestWithdrawMaxNo] = requestWithdrawInfo;

        emit RequestWithdraw(msg.sender, asToken, amount, st.requestWithdrawMaxNo, emergency);
    }

function multicall(bytes[] calldata _data) external payable override returns (bytes[] memory results) {
        results = new bytes[](_data.length);
        for (uint256 i = 0; i < _data.length; i++) {
            (bool success, bytes memory result) = address(this).delegatecall(_data[i]);

            if (!success) {
                // Next 5 lines from https://ethereum.stackexchange.com/a/83577
                if (result.length < 68) revert();
                assembly {
                    result := add(result, 0x04)
                }
                revert(abi.decode(result, (string)));
            }

            results[i] = result;
        }
    }

function transferFrom(address from, address to, uint256 value) public virtual returns (bool) {
        address spender = _msgSender();
        _spendAllowance(from, spender, value);
        _transfer(from, to, value);
        return true;
    }

function recoverUnsupportedTokens(address tokenAddress) external onlyOwner {
    if (tokenAddress == token) {
      revert RecoverSupportedToken();
    }

    IERC20 unsupportedToken = IERC20(tokenAddress);
    uint256 amount = unsupportedToken.balanceOf(address(this));

    if (amount == 0) {
      revert NoExcessTokens(tokenAddress);
    }

    LibCommon.safeTransfer(address(unsupportedToken), owner(), amount);

    emit TokensRecovered(tokenAddress);
  }
